import sqlite3, os, secrets, hashlib, hmac, re, base64, json
from datetime import datetime, timezone
DB='/app/data/huddle.db'
def connect():
    c=sqlite3.connect(DB,timeout=10,isolation_level=None)
    c.row_factory=sqlite3.Row
    c.execute('PRAGMA busy_timeout=10000')
    return c
from contextlib import contextmanager
@contextmanager
def tx():
    c=connect()
    try:
        c.execute('BEGIN IMMEDIATE'); yield c; c.execute('COMMIT')
    except: c.execute('ROLLBACK'); raise
    finally: c.close()
def now_iso(): return datetime.now(timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def init_db():
    os.makedirs('/app/data',exist_ok=True)
    c=connect(); c.execute('PRAGMA journal_mode=WAL')
    c.executescript('''
    CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
    CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER,created_at TEXT);
    CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
    CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0,last_event_id INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS members(user_id INTEGER,workspace_id INTEGER,channel_id INTEGER,role TEXT DEFAULT 'member',PRIMARY KEY(user_id,workspace_id,channel_id));
    CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS events(channel_id INTEGER,event_id INTEGER,payload TEXT,PRIMARY KEY(channel_id,event_id));
    CREATE TABLE IF NOT EXISTS global_events(id INTEGER PRIMARY KEY,payload TEXT);
    '''); c.close()
def hash_password(pw):
    salt=secrets.token_hex(16); return salt+'$'+hashlib.sha256((salt+pw).encode()).hexdigest()
def verify_password(pw,stored):
    try:
        s,h=stored.split('$',1); return hmac.compare_digest(h,hashlib.sha256((s+pw).encode()).hexdigest())
    except: return False
def issue_token(c,user_id):
    t=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?,?)',(t,user_id,now_iso())); return t
def user_for_token(token):
    if not token:return None
    c=connect(); r=c.execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(token,)).fetchone(); c.close(); return r
def user_to_json(r):
    return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
if __name__=='__main__':
    init_db()
EOF
cat > /app/server.py <<'EOF'
import argparse,re,json
from aiohttp import web
import core
parser=argparse.ArgumentParser(); parser.add_argument('--node',type=int,default=0); args=parser.parse_args()
def json_error(status,msg): return web.json_response({'error':msg},status=status)
async def read_json(req):
    try: return await req.json()
    except: return None
def require_user(req):
    h=req.headers.get('Authorization','')
    if not h.startswith('Bearer '): raise web.HTTPUnauthorized()
    u=core.user_for_token(h[7:])
    if not u: raise web.HTTPUnauthorized()
    return u
async def health(req): return web.json_response({'status':'ok','node_id':args.node})
async def register(req):
    d=await read_json(req)
    if not isinstance(d,dict) or not isinstance(d.get('username'),str) or not re.fullmatch(r'[A-Za-z0-9_]+',d.get('username','')) or not isinstance(d.get('password'),str) or len(d['password'])<8: return json_error(400,'invalid registration')
    try:
        with core.tx() as c:
            c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(d['username'],core.hash_password(d['password']),d.get('display_name') or d['username']))
            u=c.execute('SELECT * FROM users WHERE id=?',(c.lastrowid,)).fetchone(); t=core.issue_token(c,u['id'])
        return web.json_response({'user':core.user_to_json(u),'token':t},status=201)
    except: return json_error(409,'username already exists')
async def login(req):
    d=await read_json(req); c=core.connect(); u=c.execute('SELECT * FROM users WHERE username=?',(d.get('username') if isinstance(d,dict) else '',)).fetchone(); c.close()
    if not u or not isinstance(d,dict) or not core.verify_password(d.get('password',''),u['password']): return json_error(401,'invalid credentials')
    with core.tx() as c:t=core.issue_token(c,u['id'])
    return web.json_response({'user':core.user_to_json(u),'token':t})
async def me(req):
    try:u=require_user(req)
    except web.HTTPUnauthorized:return json_error(401,'unauthorized')
    return web.json_response({'user':core.user_to_json(u)})
async def ws(req):
    try: require_user(req)
    except web.HTTPUnauthorized:return json_error(401,'unauthorized')
    return web.Response(status=501)
app=web.Application(); app.router.add_get('/api/health',health); app.router.add_post('/api/auth/register',register); app.router.add_post('/api/auth/login',login); app.router.add_get('/api/auth/me',me); app.router.add_get('/api/ws',ws)
web.run_app(app,host='127.0.0.1',port=8000+args.node)
EOF
python3 -m py_compile /app/core.py /app/server.py
ls -l /app/start.sh /app/requirements.txt /app/core.py /app/server.py
```

